package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.nbt.CompoundTag;
/** Validated vanilla native brewing routes; modded and later-band routes stay unavailable. */
public final class BrewQuests {
 public record Recipe(String quest,String input,String reagent,String output,String item){
  public Recipe(String quest,String input,String reagent,String output){this(quest,input,reagent,output,"minecraft:potion");}
 }
 public static final String UNDERWATER="kingdom_smp:alchemist/j03",SPLASH="kingdom_smp:alchemist/j04";
 private static final List<Recipe> RECIPES=List.of(new Recipe("kingdom_smp:alchemist/a02","water","nether_wart","awkward"),new Recipe("kingdom_smp:alchemist/a03","awkward","glistering_melon_slice","healing"),new Recipe("kingdom_smp:alchemist/a04","awkward","sugar","swiftness"),new Recipe("kingdom_smp:alchemist/a05","awkward","blaze_powder","strength"),new Recipe("kingdom_smp:alchemist/a06","awkward","magma_cream","fire_resistance"),new Recipe("kingdom_smp:alchemist/j01","fire_resistance","redstone","long_fire_resistance"),new Recipe("kingdom_smp:alchemist/j02","healing","glowstone_dust","strong_healing"),new Recipe(UNDERWATER,"awkward","pufferfish","water_breathing"),new Recipe(UNDERWATER,"awkward","golden_carrot","night_vision"),new Recipe(SPLASH,"healing","gunpowder","healing","minecraft:splash_potion"),new Recipe(SPLASH,"swiftness","gunpowder","swiftness","minecraft:splash_potion"),new Recipe(SPLASH,"strength","gunpowder","strength","minecraft:splash_potion"),new Recipe(SPLASH,"fire_resistance","gunpowder","fire_resistance","minecraft:splash_potion"),new Recipe(SPLASH,"water_breathing","gunpowder","water_breathing","minecraft:splash_potion"),new Recipe(SPLASH,"night_vision","gunpowder","night_vision","minecraft:splash_potion"));
 private BrewQuests(){}
 public static Set<String> ids(){return RECIPES.stream().map(Recipe::quest).collect(java.util.stream.Collectors.toUnmodifiableSet());}
 public static boolean contains(String id){return id!=null&&RECIPES.stream().anyMatch(r->r.quest().equals(id));}
 public static Recipe get(String id){return RECIPES.stream().filter(r->r.quest().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Unvalidated brewing objective"));}
 public static List<Recipe> recipes(String quest){get(quest);return RECIPES.stream().filter(r->r.quest().equals(quest)).toList();}
 public static Optional<Recipe> route(String input,String reagent,String output,String item){return RECIPES.stream().filter(r->("minecraft:"+r.input()).equals(input)&&("minecraft:"+r.reagent()).equals(reagent)&&("minecraft:"+r.output()).equals(output)&&r.item().equals(item)).findFirst();}
 public static Optional<Recipe> route(String input,String reagent,String output){return route(input,reagent,output,"minecraft:potion");}
 public static Recipe fromInput(String quest,CompoundTag input,String ingredient){String potion=kind(input);return recipes(quest).stream().filter(r->("minecraft:"+r.input()).equals(potion)&&("minecraft:"+r.reagent()).equals(ingredient)).findFirst().orElseThrow(()->new IllegalArgumentException("Unvalidated native recipe inputs"));}
 public static Recipe fromJob(CompoundTag job){var inputs=job.getList("inputs",net.minecraft.nbt.Tag.TAG_COMPOUND);for(int n=0;n<3;n++)if(!inputs.getCompound(n).isEmpty())return fromInput(job.getString("quest"),inputs.getCompound(n),inputs.getCompound(3).getString("id"));throw new IllegalArgumentException("No native bottle input");}
 public static String kind(CompoundTag stack){return stack.getCompound("components").getCompound("minecraft:potion_contents").getString("potion");}
 public static boolean outputItem(String quest,String item){return recipes(quest).stream().anyMatch(r->r.item().equals(item));}
 public static void validateEncoded(String quest,CompoundTag stack){var contents=stack.getCompound("components").getCompound("minecraft:potion_contents");if(stack.getInt("count")!=1||!contents.getAllKeys().equals(Set.of("potion"))||recipes(quest).stream().noneMatch(r->stack.getString("id").equals(r.item())&&contents.getString("potion").equals("minecraft:"+r.output())))throw new IllegalArgumentException("Wrong native commissioned potion");}
 public static void goal(String quest,int total){get(quest);if(total<1||total>36||quest.equals(UNDERWATER)&&total%2!=0)throw new IllegalArgumentException("Underwater commission needs equal bounded quotas for both potion families");}
 /** Already authenticated candidates; choose physical identities by family, never by client counts. */
 public static List<Integer> select(String quest,List<CompoundTag> candidates,int required){goal(quest,required);if(candidates.size()>36)throw new IllegalArgumentException("Inventory candidate bound exceeded");List<Integer> result=new ArrayList<>();if(!quest.equals(UNDERWATER)){for(int n=0;n<Math.min(required,candidates.size());n++){validateEncoded(quest,candidates.get(n));result.add(n);}return result.size()==required?List.copyOf(result):List.of();}for(String kind:List.of("minecraft:water_breathing","minecraft:night_vision")){int quota=required/2;for(int n=0;n<candidates.size()&&quota>0;n++)if(kind(candidates.get(n)).equals(kind)){validateEncoded(quest,candidates.get(n));result.add(n);quota--;}if(quota!=0)return List.of();}return List.copyOf(result);}
 public static void validateDelivery(String quest,Collection<CompoundTag> items,int required){goal(quest,required);if(items.size()!=required)throw new IllegalArgumentException("Exact potion commission quantity required");var list=List.copyOf(items);if(select(quest,list,required).size()!=required)throw new IllegalArgumentException("Both underwater potion families must meet their quotas");}
}
